    D[i][i] = 0
for _ in range(m):
    a, b, w = int(data[p]), int(data[p + 1]), int(data[p + 2])
    p += 3
    if w < D[a][b]:
        D[a][b] = w
for k in range(1, n + 1):
    for i in range(1, n + 1):
        for j in range(1, n + 1):
            if D[i][k] + D[k][j] < D[i][j]:
                D[i][j] = D[i][k] + D[k][j]
q = int(data[p]); p += 1
out = []
for _ in range(q):
    x, y = int(data[p]), int(data[p + 1])
    p += 2
