    def fmt(n, edges, qs):
        return f"{n} {len(edges)}\n" + ''.join(f"{a} {b} {w}\n" for a, b, w in edges) + f"{len(qs)}\n" + '\n'.join(f"{x} {y}" for x, y in qs)
    tests = [
