        fmt(2, [(1, 2, 5)], [(1, 2), (2, 1)]),
        fmt(3, [(1, 2, 4), (1, 2, 2), (2, 3, 1)], [(1, 3), (3, 3)]),
        fmt(4, [(1, 2, 1), (2, 3, 1), (3, 4, 1), (1, 4, 10)], [(1, 4), (4, 1)]),
        fmt(3, [(1, 2, 10**6), (2, 3, 10**6)], [(1, 3), (2, 1)]),
    ]
    for n in (2, 3, 4, 5, 6, 8):
        for _ in range(3):
            m = rng.randint(0, 3 * n)
            edges = [(rng.randint(1, n), rng.randint(1, n), rng.randint(1, 20)) for _ in range(m)]
            qs = [(rng.randint(1, n), rng.randint(1, n)) for _ in range(rng.randint(1, 5))]
            tests.append(fmt(n, edges, qs))
    def big(n, m, q, wmax, chain=False):
        edges = []
        if chain:
            # chain stored in reverse order so naive relaxation needs many rounds
            edges = [(i, i + 1, rng.randint(1, wmax)) for i in range(n - 1, 0, -1)]
        while len(edges) < m:
            a, b = rng.randint(1, n), rng.randint(1, n)
            edges.append((a, b, rng.randint(1, wmax)))
        rng.shuffle(edges) if not chain else None
        srcs = rng.sample(range(1, n + 1), q)
        qs = [(s, rng.randint(1, n)) for s in srcs]
        if chain:
            qs[0] = (1, n)
        return fmt(n, edges, qs)
    tests.append(big(2000, 10000, 40, 10**6))
    tests.append(big(2000, 10000, 40, 10))
    tests.append(big(2000, 10000, 40, 10**6, chain=True))
    tests.append(big(2000, 2000, 40, 10**6))
    return tests

