    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        int n = (int) in.nval;
        in.nextToken();
        int m = (int) in.nval;
        int[][] edges = new int[m][3];
        for (int i = 0; i < m; i++) {
            for (int j = 0; j < 3; j++) {
                in.nextToken();
                edges[i][j] = (int) in.nval;
            }
        }
        in.nextToken();
        int q = (int) in.nval;
        int[][] queries = new int[q][2];
        for (int i = 0; i < q; i++) {
            in.nextToken(); queries[i][0] = (int) in.nval;
            in.nextToken(); queries[i][1] = (int) in.nval;
        }
        long[] res = minLatency(n, edges, queries);
        StringBuilder sb = new StringBuilder();
        for (long r : res) sb.append(r).append("\n");
        System.out.print(sb);
    }
}
